## 2. **API Routes**

### `/app/api/boost/checkout/route.ts`
```typescript
import { NextRequest, NextResponse } from 'next/server';
import Stripe from 'stripe';
import prisma from '@/lib/prisma';

const stripe = new Stripe(process.env.STRIPE_SECRET_KEY!, {
  apiVersion: '2024-06-20',
});

export async function POST(request: NextRequest) {
  try {
    const { photoId, amount, charityName, boosterId } = await request.json();

    if (!photoId || !amount || amount < 5 || !charityName) {
      return NextResponse.json({ error: 'Invalid input' }, { status: 400 });
    }

    const photo = await prisma.photo.findUnique({
      where: { id: photoId },
      include: { user: { select: { name: true } } },
    });

    if (!photo) {
      return NextResponse.json({ error: 'Photo not found' }, { status: 404 });
    }

    const amountCents = Math.round(amount * 100);
    const photographerName = photo.user?.name || 'Anonymous';

    const session = await stripe.checkout.sessions.create({
      payment_method_types: ['card'],
      line_items: [{
        price_data: {
          currency: 'usd',
          product_data: {
            name: `Prize Boost: ${photographerName}'s Photo`,
            description: `❤️ Supporting ${charityName}`,
            images: [photo.blobUrl].filter(Boolean),
          },
          unit_amount: amountCents,
        },
        quantity: 1,
      }],
      mode: 'payment',
      success_url: `${process.env.NEXT_PUBLIC_BASE_URL}/boost/success?session_id={CHECKOUT_SESSION_ID}&photoId=${photoId}`,
      cancel_url: `${process.env.NEXT_PUBLIC_BASE_URL}/leaderboard`,
      metadata: {
        photoId,
        charityName,
        amount: amount.toString(),
        boosterId: boosterId || 'anonymous',
        photographerName,
      },
      submit_type: 'donate',
    });

    return NextResponse.json({ url: session.url, sessionId: session.id });
  } catch (error) {
    console.error('Checkout error:', error);
    return NextResponse.json({ error: 'Server error' }, { status: 500 });
  }
}
```

### `/app/api/boost/webhook/route.ts`
```typescript
import { NextRequest, NextResponse } from 'next/server';
import Stripe from 'stripe';
import prisma from '@/lib/prisma';

const stripe = new Stripe(process.env.STRIPE_SECRET_KEY!);

export async function POST(request: NextRequest) {
  const body = await request.text();
  const signature = request.headers.get('stripe-signature')!;

  try {
    const event = stripe.webhooks.constructEvent(
      body,
      signature,
      process.env.STRIPE_WEBHOOK_SECRET!
    );

    if (event.type === 'checkout.session.completed') {
      const session = event.data.object as Stripe.Checkout.Session;

      if (session.payment_status === 'paid') {
        const { photoId, charityName, boosterId, amount } = session.metadata!;

        if (photoId && charityName) {
          const totalAmount = parseFloat(amount || '0');
          const charityAmount = totalAmount * 0.20;
          const platformFee = totalAmount * 0.05;
          const prizeBoostAmount = totalAmount * 0.75;

          await prisma.$transaction(async (tx) => {
            await tx.prizeBoost.create({
              data: {
                photoId,
                boosterId: boosterId === 'anonymous' ? null : boosterId,
                amount: totalAmount,
                charityAmount,
                platformFee,
                charityName,
                stripeSessionId: session.id,
              },
            });

            await tx.photo.update({
              where: { id: photoId },
              data: {
                prizeBoost: { increment: prizeBoostAmount },
                boostCount: { increment: 1 },
              },
            });
          });
        }
      }
    }

    return NextResponse.json({ received: true });
  } catch (err: any) {
    console.error('Webhook error:', err.message);
    return NextResponse.json({ error: 'Webhook failed' }, { status: 400 });
  }
}
```

